package edu.minibank.util;
import edu.minibank.model.annotation.Id; import java.lang.reflect.Field; import java.util.*; import java.util.concurrent.ConcurrentHashMap;
public class Repository<T> {private final Map<String,T> items=new ConcurrentHashMap<>(); public T save(T entity){Objects.requireNonNull(entity);try{for(Class<?> type=entity.getClass();type!=null;type=type.getSuperclass())for(Field f:type.getDeclaredFields())if(f.isAnnotationPresent(Id.class)){f.setAccessible(true);Object key=f.get(entity);if(key==null)throw new IllegalArgumentException("@Id cannot be null");items.put(key.toString(),entity);return entity;}throw new IllegalArgumentException("No @Id field on "+entity.getClass().getName());}catch(IllegalAccessException e){throw new IllegalStateException(e);}} public T findById(String id){return items.get(id);} public ArrayList<T> findAll(){return new ArrayList<>(items.values());} public boolean delete(String id){return items.remove(id)!=null;} @SafeVarargs public final void saveAll(T... entities){for(T entity:entities)save(entity);} public int size(){return items.size();} public static <N extends Number> double average(N[] values){if(values.length==0)return 0;double sum=0;for(N n:values)sum+=n.doubleValue();return sum/values.length;}}
